select entity_key, metric_value, rank() over (partition by entity_group order by metric_value desc) as value_rank, dense_rank() over (partition by entity_group order by metric_value desc) as dense_value_rank, percent_rank() over (partition by entity_group order by metric_value desc) as value_percent_rank, ntile(4) over (order by metric_value) as value_quartile from anon.metrics_store